CREATE TABLE IF NOT EXISTS op_config_info (id BIGINT PRIMARY KEY, name VARCHAR(255), `key` VARCHAR(255), `value` VARCHAR(255), created_at TIMESTAMP);
CREATE TABLE IF NOT EXISTS tbl_user (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, email VARCHAR(255), name VARCHAR(255), profile_image VARCHAR(255), status INT, created_at TIMESTAMP, updated_at TIMESTAMP, deleted_at TIMESTAMP);
